// Simple threshold-based alert detection
const d = $input.first().json;
const alerts = [];

if (d.air_quality.us_aqi >= 151) {
  alerts.push({ type: 'AIR_QUALITY', level: d.air_quality.us_aqi >= 201 ? 'SEVERE' : 'HIGH', message: `US AQI ${d.air_quality.us_aqi} - unhealthy air quality in Lahore` });
}
if (d.weather.rain_mm >= 15) {
  alerts.push({ type: 'FLOOD_RISK', level: d.weather.rain_mm >= 30 ? 'SEVERE' : 'MODERATE', message: `Heavy rainfall detected: ${d.weather.rain_mm}mm - elevated flood risk in low-lying areas` });
}
if (d.weather.temperature_c >= 42) {
  alerts.push({ type: 'HEAT', level: d.weather.temperature_c >= 45 ? 'SEVERE' : 'HIGH', message: `Extreme heat: ${d.weather.temperature_c}°C` });
}

d.alerts = alerts;
return [{ json: d }];

// Normalize OSM elements into a flat facility list grouped by category
const raw = $input.first().json;
const elements = raw.elements || [];

function categorize(tags) {
  if (tags.amenity === 'hospital') return 'hospital';
  if (tags.amenity === 'school') return 'school';
  if (tags.amenity === 'police') return 'police';
  if (tags.leisure === 'park') return 'park';
  return 'other';
}

const facilities = elements.map(el => {
  const lat = el.lat ?? el.center?.lat;
  const lon = el.lon ?? el.center?.lon;
  return {
    id: el.id,
    type: categorize(el.tags || {}),
    name: el.tags?.name || 'Unnamed',
    lat,
    lon
  };
}).filter(f => f.lat && f.lon);

return [{
  json: {
    city: 'Lahore',
    ingested_at: new Date().toISOString(),
    facility_count: facilities.length,
    facilities
  }
}];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const weather = safeGet('Webhook - Weather') || {};
const airQuality = safeGet('Webhook - Air Quality') || {};
const openaq = safeGet('Webhook - OpenAQ');
const forex = safeGet('Webhook - Forex') || {};
const kse = safeGet('Webhook - PSX Stocks');
const kmi = safeGet('Webhook - PSX KMI30');
const goldRaw = safeGet('Webhook - Gold');
const flightsRaw = safeGet('Webhook - Flights');
const tavily = safeGet('Webhook - Tavily Civic');

const rates = forex.rates || {};
const usdToPkr = rates.PKR || null;
const usdToSar = rates.SAR || null;
const usdToAed = rates.AED || null;
const sarToPkr = (usdToPkr && usdToSar) ? usdToPkr / usdToSar : null;
const aedToPkr = (usdToPkr && usdToAed) ? usdToPkr / usdToAed : null;

const GRAMS_PER_OZ = 31.1034768;
const GRAMS_PER_TOLA = 11.6638038;
let gold24kPerTola = null, gold22kPerTola = null, silverPerTola = null;
if (goldRaw && goldRaw.xau && typeof goldRaw.xau.price === 'number') {
  const goldPkrPerGram = goldRaw.xau.price;
  gold24kPerTola = goldPkrPerGram * GRAMS_PER_TOLA;
  gold22kPerTola = gold24kPerTola * (22/24);
}
if (goldRaw && typeof goldRaw.silver_usd_oz === 'number' && usdToPkr) {
  const silverUsdPerGram = goldRaw.silver_usd_oz / GRAMS_PER_OZ;
  silverPerTola = silverUsdPerGram * usdToPkr * GRAMS_PER_TOLA;
}

function latestIndexPoint(resp) {
  if (resp && resp.status === 1 && Array.isArray(resp.data) && resp.data.length > 0) {
    const point = resp.data[0];
    return { value: point[1], as_of: new Date(point[0] * 1000).toISOString() };
  }
  return null;
}
const kse100 = latestIndexPoint(kse);
const kmi30 = latestIndexPoint(kmi);

let flights = [];
if (flightsRaw && Array.isArray(flightsRaw.states)) {
  flights = flightsRaw.states.map(s => ({
    callsign: (s[1] || '').trim(),
    origin_country: s[2],
    longitude: s[5],
    latitude: s[6],
    altitude_m: s[7],
    velocity_ms: s[9],
    on_ground: s[8]
  }));
}

let civicSearch = { available: false, reason: 'Tavily API key not configured' };
if (tavily && Array.isArray(tavily.results) && tavily.results.length > 0) {
  civicSearch = {
    available: true,
    source: 'Tavily Search API',
    results: tavily.results.slice(0, 3).map(r => ({ title: r.title, url: r.url, snippet: (r.content || '').slice(0, 220) }))
  };
} else if (tavily && tavily.error) {
  civicSearch = { available: false, reason: 'Tavily error: ' + (typeof tavily.error === 'string' ? tavily.error : JSON.stringify(tavily.error)) };
}

return [{
  json: {
    city: 'Lahore',
    ingested_at: new Date().toISOString(),
    weather: {
      temperature_c: weather.current ? weather.current.temperature_2m : null,
      humidity_pct: weather.current ? weather.current.relative_humidity_2m : null,
      precipitation_mm: weather.current ? weather.current.precipitation : null,
      rain_mm: weather.current ? weather.current.rain : null,
      wind_speed_kmh: weather.current ? weather.current.wind_speed_10m : null,
      wind_direction_deg: weather.current ? weather.current.wind_direction_10m : null,
      pressure_hpa: weather.current ? weather.current.surface_pressure : null,
      weather_code: weather.current ? weather.current.weather_code : null,
      hourly_forecast: weather.hourly || null,
      source: 'Open-Meteo Forecast API (api.open-meteo.com)'
    },
    air_quality: {
      pm2_5: airQuality.current ? airQuality.current.pm2_5 : null,
      pm10: airQuality.current ? airQuality.current.pm10 : null,
      co: airQuality.current ? airQuality.current.carbon_monoxide : null,
      no2: airQuality.current ? airQuality.current.nitrogen_dioxide : null,
      so2: airQuality.current ? airQuality.current.sulphur_dioxide : null,
      ozone: airQuality.current ? airQuality.current.ozone : null,
      us_aqi: airQuality.current ? airQuality.current.us_aqi : null,
      european_aqi: airQuality.current ? airQuality.current.european_aqi : null,
      hourly_forecast: airQuality.hourly || null,
      source: 'Open-Meteo Air Quality API (air-quality-api.open-meteo.com)'
    },
    openaq_ground_stations: openaq ? (openaq.results || []) : [],
    openaq_source: 'OpenAQ v3 API (api.openaq.org)',
    markets: {
      forex: { usd_pkr: usdToPkr, sar_pkr: sarToPkr, aed_pkr: aedToPkr, available: !!usdToPkr, source: 'open.er-api.com (free, no key)' },
      gold_silver: {
        gold_24k_per_tola_pkr: gold24kPerTola,
        gold_22k_per_tola_pkr: gold22kPerTola,
        silver_per_tola_pkr: silverPerTola,
        available: !!gold24kPerTola,
        source: 'xaus.com Gold Data API (global spot, PKR-converted)',
        note: 'Global spot converted rate — not the official APGJA Sarafa Association local rate'
      },
      psx: { kse100, kmi30, available: !!kse100, source: 'PSX Data Portal (dps.psx.com.pk) — official public timeseries endpoint' }
    },
    flights: {
      available: flights.length > 0,
      count: flights.length,
      aircraft: flights,
      source: 'OpenSky Network API (opensky-network.org) — anonymous tier, bounding box around Lahore'
    },
    civic: {
      food_prices: { available: false, reason: 'No public JSON API - Qeemat Punjab (PITB) only publishes PDF/HTML bulletins', fallback: civicSearch },
      lpg_price: { available: false, reason: 'OGRA publishes notifications, not a queryable API', fallback: civicSearch },
      power_outages: { available: false, reason: 'K-Electric/LESCO/FESCO feeder status has no public API', fallback: civicSearch },
      trains: { available: false, reason: 'Pakistan Railways RTS has no public API' },
      traffic: { available: false, reason: 'City Traffic Police / NHMP advisories are not published as an API', fallback: civicSearch }
    }
  }
}];

const d = $input.first().json;
const alerts = [];
if (d.air_quality.us_aqi >= 151) { alerts.push({ type: 'AIR_QUALITY', level: d.air_quality.us_aqi >= 201 ? 'SEVERE' : 'HIGH', message: `US AQI ${d.air_quality.us_aqi} - unhealthy air quality in Lahore` }); }
if (d.weather.rain_mm >= 15) { alerts.push({ type: 'FLOOD_RISK', level: d.weather.rain_mm >= 30 ? 'SEVERE' : 'MODERATE', message: `Heavy rainfall detected: ${d.weather.rain_mm}mm - elevated flood risk in low-lying areas` }); }
if (d.weather.temperature_c >= 42) { alerts.push({ type: 'HEAT', level: d.weather.temperature_c >= 45 ? 'SEVERE' : 'HIGH', message: `Extreme heat: ${d.weather.temperature_c}°C` }); }
d.alerts = alerts;
return [{ json: d }];

function safeGet(nodeName) { try { const item = $(nodeName).first(); return item ? item.json : null; } catch (e) { return null; } }
const weather = safeGet('Open-Meteo: Weather') || {};
const airQuality = safeGet('Open-Meteo: Air Quality') || {};
const openaq = safeGet('OpenAQ: Lahore Stations') || {};

return [{
  json: {
    city: 'Lahore',
    ingested_at: new Date().toISOString(),
    weather: {
      temperature_c: weather.current ? weather.current.temperature_2m : null,
      humidity_pct: weather.current ? weather.current.relative_humidity_2m : null,
      precipitation_mm: weather.current ? weather.current.precipitation : null,
      rain_mm: weather.current ? weather.current.rain : null,
      wind_speed_kmh: weather.current ? weather.current.wind_speed_10m : null,
      wind_direction_deg: weather.current ? weather.current.wind_direction_10m : null,
      pressure_hpa: weather.current ? weather.current.surface_pressure : null,
      weather_code: weather.current ? weather.current.weather_code : null,
      hourly_forecast: weather.hourly || null
    },
    air_quality: {
      pm2_5: airQuality.current ? airQuality.current.pm2_5 : null,
      pm10: airQuality.current ? airQuality.current.pm10 : null,
      co: airQuality.current ? airQuality.current.carbon_monoxide : null,
      no2: airQuality.current ? airQuality.current.nitrogen_dioxide : null,
      so2: airQuality.current ? airQuality.current.sulphur_dioxide : null,
      ozone: airQuality.current ? airQuality.current.ozone : null,
      us_aqi: airQuality.current ? airQuality.current.us_aqi : null,
      european_aqi: airQuality.current ? airQuality.current.european_aqi : null,
      hourly_forecast: airQuality.hourly || null
    },
    openaq_ground_stations: openaq.results || []
  }
}];
